using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class YachtPortAtlasAudit{static YachtPortAtlasAudit(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("YachtPortAtlasAudit.request"))return;File.Delete("YachtPortAtlasAudit.request");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var log=new StringBuilder();foreach(var root in scene.GetRootGameObjects())foreach(var t in root.GetComponentsInChildren<Transform>(true))if(t.name.ToLower().Contains("yatch")||t.name.ToLower().Contains("yacht")){log.AppendLine("PORT "+AnimationUtility.CalculateTransformPath(t,root.transform)+" root="+root.name);foreach(var f in t.GetComponentsInChildren<MeshFilter>(true)){var r=f.GetComponent<Renderer>();if(f.sharedMesh.isReadable){var vertices=f.sharedMesh.vertices.Select(f.transform.TransformPoint).ToArray();log.AppendLine("Y LEVELS "+string.Join(";",vertices.GroupBy(v=>Mathf.Round(v.y*10)/10).OrderByDescending(g=>g.Count()).Take(10).Select(g=>g.Key+":"+g.Count()))+" transform="+f.transform.position+" scale="+f.transform.lossyScale);File.WriteAllLines("FinalEnvironmentRoadReview/YardWorldPoints.csv",vertices.Select(v=>v.x.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+v.y.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+v.z.ToString("R",System.Globalization.CultureInfo.InvariantCulture)));}log.AppendLine("MESH "+f.name+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" bounds="+(r?r.bounds.ToString():"none")+" materials="+(r?string.Join(",",r.sharedMaterials.Select(m=>m?m.name:"null")):"none"));}}File.WriteAllText("FinalEnvironmentRoadReview/YachtPortAtlasAudit.txt",log.ToString());}}
